const output = [];
const now = Date.now();

function stripHtml(value) {
  return String(value || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#39;/gi, "'")
    .replace(/&quot;/gi, '"')
    .replace(/\s+/g, ' ')
    .trim();
}

function fieldTextFromHtml(value) {
  return String(value || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?\s*>/gi, '\n')
    .replace(/<\/(?:p|div|tr|li|h[1-6])\s*>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#39;/gi, "'")
    .replace(/&quot;/gi, '"')
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function extractLatestAuthoredText(htmlValue, fallbackValue) {
  const html = String(htmlValue || '');
  const htmlMarkers = [
    /<div[^>]+id=["']divRplyFwdMsg["'][^>]*>/i,
    /<div[^>]+class=["'][^"']*gmail_quote[^"']*["'][^>]*>/i,
    /<blockquote[^>]*(?:type=["']cite["'])?[^>]*>/i,
    /<!--\s*Original Message\s*-->/i,
  ];
  let htmlCut = html.length;
  for (const marker of htmlMarkers) {
    const match = marker.exec(html);
    if (match && match.index < htmlCut) htmlCut = match.index;
  }

  const text = fieldTextFromHtml(html ? html.slice(0, htmlCut) : fallbackValue || '');
  const lines = text.split('\n');
  const textMarkers = [
    /^\s*-{2,}\s*(?:ursprüngliche nachricht|original message)\s*-{2,}\s*$/i,
    /^\s*(?:von|from)\s*:\s*.+$/i,
    /^\s*(?:gesendet|sent)\s*:\s*.+$/i,
    /^\s*am\s+.+\s+schrieb\s+.+:\s*$/i,
    /^\s*on\s+.+\s+wrote\s*:\s*$/i,
  ];
  let lineCut = lines.length;
  for (let index = 0; index < lines.length; index += 1) {
    if (textMarkers.some((marker) => marker.test(lines[index]))) {
      lineCut = index;
      break;
    }
  }

  const authored = lines.slice(0, lineCut).join('\n').trim();
  return (authored || fieldTextFromHtml(fallbackValue || '')).slice(0, 12000);
}

function normalizeEmailAddress(value) {
  const candidate = String(value || '').trim().toLowerCase().replace(/[>,;.)]+$/, '');
  return /^[a-z0-9.!#$%&'*+/=?^_{|}~-]+@[a-z0-9.-]+\.[a-z]{2,}$/i.test(candidate) ? candidate : '';
}

function normalizePhone(value) {
  const raw = String(value || '').trim();
  const digits = raw.replace(/\D/g, '');
  if (!digits) return '';
  if (raw.startsWith('+')) return '+' + digits;
  if (digits.startsWith('00')) return '+' + digits.slice(2);
  if (digits.startsWith('0')) return '+49' + digits.slice(1);
  if (digits.startsWith('49')) return '+' + digits;
  return '+' + digits;
}

for (const item of $input.all()) {
  const email = item.json || {};
  const messageId = String(email.id || '').trim();
  const conversationId = String(email.conversationId || '').trim();
  const subject = String(email.subject || '(kein Betreff)').trim().slice(0, 500);
  const sourceFromEmail = normalizeEmailAddress(email.from?.emailAddress?.address || '');
  const sourceFromName = String(email.from?.emailAddress?.name || '').trim().slice(0, 200);
  const receivedAt = String(email.receivedDateTime || '');
  const internetMessageId = String(email.internetMessageId || '').trim().slice(0, 500);
  const receivedMs = Date.parse(receivedAt);
  const bodyHtml = String(email.body?.content || '');
  const fullBodyText = stripHtml(bodyHtml || email.bodyPreview || '').slice(0, 12000);
  let latestMessageText = extractLatestAuthoredText(bodyHtml, email.bodyPreview || '').slice(0, 12000);
  let bodyText = latestMessageText || fullBodyText;
  let knowledgeQuery = (subject + ' ' + latestMessageText.slice(0, 1200))
    .replace(/https?:\/\/\S+/gi, ' ')
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, ' ')
    .replace(/[^\p{L}\p{N}\s-]+/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 240);
  const fieldText = fieldTextFromHtml(bodyHtml || email.bodyPreview || '').slice(0, 16000);
  const headers = Array.isArray(email.internetMessageHeaders) ? email.internetMessageHeaders : [];
  const autoSubmitted = String(headers.find((h) => String(h.name || '').toLowerCase() === 'auto-submitted')?.value || '').toLowerCase();

  const replyTo = Array.isArray(email.replyTo) ? email.replyTo : [];
  const externalReplyToEntry = replyTo.find((entry) => {
    const address = normalizeEmailAddress(entry?.emailAddress?.address || '');
    return address && !address.endsWith('@neontrip.de');
  });
  const externalReplyToEmail = normalizeEmailAddress(externalReplyToEntry?.emailAddress?.address || '');
  const externalReplyToName = String(externalReplyToEntry?.emailAddress?.name || '').trim().slice(0, 200);
  const bodyCustomerEmailMatch = fieldText.match(/(?:^|\n)\s*(?:e-mail|email|direkt antworten)\s*:\s*([^\s<>]+)/i);
  const bodyCustomerEmail = normalizeEmailAddress(bodyCustomerEmailMatch?.[1] || '');
  const customerNameMatch = fieldText.match(/(?:^|\n)\s*kunde\s*:\s*([^\n]+)/i);
  const firstNameMatch = fieldText.match(/(?:^|\n)\s*vorname\s*:\s*([^\n]+)/i);
  const lastNameMatch = fieldText.match(/(?:^|\n)\s*nachname\s*:\s*([^\n]+)/i);
  const formCustomerName = [firstNameMatch?.[1], lastNameMatch?.[1]].map((value) => String(value || '').trim()).filter(Boolean).join(' ');
  const bodyCustomerName = String(customerNameMatch?.[1] || formCustomerName || '').trim().slice(0, 200);

  const relaySignals = [
    /(?:^|\n)\s*direkt antworten\s*:/i.test(fieldText),
    /neue\s+(?:frage|nachricht)[^\n]{0,80}neontrip\s+angebot/i.test(fieldText),
    /https:\/\/angebote\.neontrip\.de\/offer\/[A-Za-z0-9_-]{12,}/i.test(bodyHtml + ' ' + fieldText),
    /^frage\s+zum\s+angebot\b/i.test(subject),
  ].filter(Boolean).length;
  const trustedSupportRelay = sourceFromEmail === 'support@neontrip.de'
    && Boolean(externalReplyToEmail)
    && relaySignals >= 2
    && (!bodyCustomerEmail || bodyCustomerEmail === externalReplyToEmail);
  const knownFormRelays = new Set(['info@nerdy-apps.com']);
  const formRelaySignals = [
    /^neue\s+anfrage\s+neontrip\b/i.test(subject),
    /(?:^|\n)\s*new unique identifier\s*:/i.test(fieldText),
    /(?:^|\n)\s*vorname\s*:/i.test(fieldText) && /(?:^|\n)\s*nachname\s*:/i.test(fieldText),
    /(?:^|\n)\s*nachricht\s*:/i.test(fieldText),
  ].filter(Boolean).length;
  const trustedFormRelay = knownFormRelays.has(sourceFromEmail)
    && Boolean(externalReplyToEmail)
    && bodyCustomerEmail === externalReplyToEmail
    && formRelaySignals >= 3;
  const toAddresses = Array.isArray(email.toRecipients)
    ? email.toRecipients.map((entry) => normalizeEmailAddress(entry?.emailAddress?.address || '')).filter(Boolean)
    : [];
  const whatsappSubjectMatch = subject.match(/^WhatsApp\s+von\s+(.+?)\s*\|\s*(\+?\d[\d\s()/-]{7,})\s*$/i);
  const whatsappBodyPhoneMatch = fieldText.match(/(?:^|\n)\s*Telefon\s*:\s*([^\n]+)/i);
  const whatsappTrackingMatch = fieldText.match(/(?:^|\n)\s*Tracking-ID\s*:\s*(WA-[A-Za-z0-9_-]{4,})/i);
  const whatsappMessageMatch = fieldText.match(/(?:^|\n)\s*Nachricht\s*:\s*([\s\S]*?)(?=\n\s*So antwortest du\s*:|\n\s*Tracking-ID\s*:|$)/i);
  const whatsappPhone = normalizePhone(whatsappSubjectMatch?.[2] || whatsappBodyPhoneMatch?.[1] || '');
  const whatsappBodyPhone = normalizePhone(whatsappBodyPhoneMatch?.[1] || '');
  const whatsappMarkersValid = /Neue\s+WhatsApp-Nachricht/i.test(fieldText)
    && /(?:^|\n)\s*Telefon\s*:/i.test(fieldText)
    && /(?:^|\n)\s*Typ\s*:/i.test(fieldText)
    && /(?:^|\n)\s*Nachricht\s*:/i.test(fieldText)
    && /(?:^|\n)\s*So antwortest du\s*:/i.test(fieldText)
    && Boolean(whatsappTrackingMatch);
  const trustedWhatsAppRelay = sourceFromEmail === 'support@neontrip.de'
    && toAddresses.includes('support@neontrip.de')
    && Boolean(whatsappSubjectMatch)
    && whatsappMarkersValid
    && Boolean(whatsappPhone)
    && (!whatsappBodyPhone || whatsappBodyPhone === whatsappPhone);
  const whatsappCustomerName = String(whatsappSubjectMatch?.[1] || '').trim().slice(0, 200);
  const whatsappCustomerEmail = bodyCustomerEmail && !bodyCustomerEmail.endsWith('@neontrip.de') ? bodyCustomerEmail : '';
  const whatsappCustomerMessage = String(whatsappMessageMatch?.[1] || '').trim().slice(0, 12000);
  const whatsappSyntheticEmail = whatsappPhone
    ? 'wa+' + whatsappPhone.replace(/\D/g, '') + '@relay.neontrip.invalid'
    : '';

  if (trustedWhatsAppRelay && whatsappCustomerMessage) {
    latestMessageText = whatsappCustomerMessage;
    bodyText = whatsappCustomerMessage;
    knowledgeQuery = (subject + ' ' + whatsappCustomerMessage.slice(0, 1200))
      .replace(/https?:\/\/\S+/gi, ' ')
      .replace(/[^\p{L}\p{N}\s-]+/gu, ' ')
      .replace(/\s+/g, ' ')
      .trim()
      .slice(0, 240);
  }

  const trustedRelay = trustedSupportRelay || trustedFormRelay || trustedWhatsAppRelay;
  const fromEmail = trustedWhatsAppRelay
    ? (whatsappCustomerEmail || whatsappSyntheticEmail)
    : (trustedRelay ? externalReplyToEmail : sourceFromEmail);
  const usableReplyToName = externalReplyToName && normalizeEmailAddress(externalReplyToName) !== externalReplyToEmail
    ? externalReplyToName
    : '';
  const fromName = trustedWhatsAppRelay
    ? (whatsappCustomerName || whatsappPhone || 'WhatsApp-Kontakt')
    : (trustedRelay ? (usableReplyToName || bodyCustomerName || externalReplyToEmail) : sourceFromName);

  const emailDomain = String(fromEmail.split('@')[1] || '').toLowerCase();
  const publicEmailDomains = new Set([
    'gmail.com', 'googlemail.com', 'outlook.com', 'outlook.de', 'hotmail.com', 'hotmail.de',
    'live.com', 'live.de', 'msn.com', 'yahoo.com', 'yahoo.de', 'icloud.com', 'me.com',
    'web.de', 'gmx.de', 'gmx.net', 'mail.de', 'freenet.de', 't-online.de', 'aol.com',
    'proton.me', 'protonmail.com', 'posteo.de', 'fastmail.com', 'yandex.com', 'yandex.ru',
    'neontrip.de', 'example.com',
  ]);
  const organizationLookupEnabled = !trustedWhatsAppRelay
    && Boolean(emailDomain)
    && emailDomain.includes('.')
    && !publicEmailDomains.has(emailDomain);

  const historyText = (subject + '\n' + latestMessageText).toLowerCase();
  const yearWordValues = {
    einem: 1, ein: 1, einen: 1, eins: 1,
    zwei: 2, drei: 3, vier: 4, fuenf: 5, fünf: 5,
  };
  const agoMatch = historyText.match(/\bvor\s+(einem|ein|einen|eins|zwei|drei|vier|fuenf|fünf|\d{1,2})\s+jahr(?:en)?\b/i);
  const agoRaw = String(agoMatch?.[1] || '').toLowerCase();
  const agoYears = agoRaw ? (Number(agoRaw) || yearWordValues[agoRaw] || 0) : 0;
  const currentYear = new Date(now).getUTCFullYear();
  const mentionedYears = Array.from(historyText.matchAll(/\b(20\d{2})\b/g))
    .map((match) => Number(match[1]))
    .filter((year) => year >= currentYear - 5 && year <= currentYear);
  const generalHistoricalCue = /\b(damals|früher|frueher|historisch|alte[nsr]?\s+(?:bestellung|auftrag|angebot)|frühere[nsr]?\s+(?:bestellung|auftrag|angebot))\b/i.test(historyText);
  const explicitHistoricalRequest = Boolean(agoYears || mentionedYears.length || generalHistoricalCue);
  let contextWindowReason = 'default_15_months';
  let contextSinceDate = new Date(now);
  contextSinceDate.setUTCMonth(contextSinceDate.getUTCMonth() - 15);

  if (agoYears) {
    contextSinceDate = new Date(now);
    contextSinceDate.setUTCFullYear(contextSinceDate.getUTCFullYear() - Math.min(5, agoYears));
    contextSinceDate.setUTCMonth(contextSinceDate.getUTCMonth() - 6);
    contextWindowReason = 'explicit_' + Math.min(5, agoYears) + '_years_ago';
  } else if (mentionedYears.length) {
    contextSinceDate = new Date(Date.UTC(Math.min(...mentionedYears), 0, 1));
    contextWindowReason = 'explicit_calendar_year';
  } else if (generalHistoricalCue) {
    contextSinceDate = new Date(now);
    contextSinceDate.setUTCMonth(contextSinceDate.getUTCMonth() - 36);
    contextWindowReason = 'explicit_historical_cue_36_months';
  }

  const historyFloor = new Date(now);
  historyFloor.setUTCFullYear(historyFloor.getUTCFullYear() - 5);
  if (contextSinceDate < historyFloor) contextSinceDate = historyFloor;
  const contextSince = contextSinceDate.toISOString();
  const contextSinceKql = String(contextSinceDate.getUTCMonth() + 1).padStart(2, '0')
    + '/' + String(contextSinceDate.getUTCDate()).padStart(2, '0')
    + '/' + contextSinceDate.getUTCFullYear();
  const organizationSearchTerm = organizationLookupEnabled ? emailDomain : fromEmail;
  const organizationSearchKql = organizationLookupEnabled
    ? '"(from:' + emailDomain + ' OR to:' + emailDomain + ' OR cc:' + emailDomain + ') AND received>=' + contextSinceKql + '"'
    : '"participants:' + fromEmail + ' AND received>=' + contextSinceKql + '"';

  const automatedSender = /(^|[._-])(no-?reply|noreply|mailer-daemon|postmaster)([._@+-]|$)/i.test(sourceFromEmail);
  const automatedSubject = /^(automatische antwort|automatic reply|out of office|abwesenheitsnotiz|unzustellbar|undeliverable|delivery status notification)/i.test(subject);
  const internalSender = sourceFromEmail.endsWith('@neontrip.de');
  const tooOld = Number.isFinite(receivedMs) && now - receivedMs > 6 * 60 * 60 * 1000;
  const isAutomated = automatedSender || automatedSubject || (autoSubmitted && autoSubmitted !== 'no');

  const skipReasons = [];
  if (!messageId) skipReasons.push('missing_message_id');
  if (!conversationId) skipReasons.push('missing_conversation_id');
  if (!sourceFromEmail || !fromEmail) skipReasons.push('missing_sender');
  if (internalSender && !(trustedSupportRelay || trustedWhatsAppRelay)) skipReasons.push('internal_sender');
  if (isAutomated) skipReasons.push('automated_message');
  if (tooOld) skipReasons.push('older_than_six_hours');

  if (skipReasons.length) {
    output.push({
      json: {
        shouldProcess: false,
        skipReason: skipReasons.join(','),
        messageId,
        conversationId,
        subject,
        sourceFromEmail,
        receivedAt,
        _startTime: now,
      },
    });
    continue;
  }

  const tokenMatch = (bodyHtml + ' ' + bodyText).match(/(?:[?&]token=|\/(?:angebot|quote|offer)\/)([A-Za-z0-9_-]{12,})/i);
  const quoteToken = tokenMatch ? tokenMatch[1] : '';
  const offerUrlMatch = (bodyHtml + ' ' + fieldText).match(/https:\/\/angebote\.neontrip\.de\/offer\/[A-Za-z0-9_-]{12,}/i);
  const offerUrl = offerUrlMatch ? offerUrlMatch[0] : '';
  const quoteNumberMatch = (subject + '\n' + fieldText).match(/(?:angebot(?:\s+a\/n)?\s*:?\s*|\bA\/N\s*)(\d{3,})/i);
  const quoteNumber = quoteNumberMatch ? 'A/N ' + quoteNumberMatch[1] : '';
  const offerLookupQuery = offerUrl || quoteNumber || (organizationLookupEnabled ? '@' + emailDomain : fromEmail);
  const offerFilters = [
    'contact_email.ilike.' + fromEmail,
    'billing_email.ilike.' + fromEmail,
    'original_email.ilike.' + fromEmail,
  ];
  if (organizationLookupEnabled) {
    offerFilters.push('contact_email.ilike.*@' + emailDomain);
    offerFilters.push('billing_email.ilike.*@' + emailDomain);
    offerFilters.push('original_email.ilike.*@' + emailDomain);
  }
  if (quoteToken) offerFilters.push('token.eq.' + quoteToken);
  const orderFilters = ['email.eq.' + fromEmail];
  if (organizationLookupEnabled) orderFilters.push('email.ilike.*@' + emailDomain);

  output.push({
    json: {
      messageId,
      shouldProcess: true,
      skipReason: '',
      conversationId,
      subject,
      internetMessageId,
      fromEmail,
      fromName,
      sourceFromEmail,
      sourceFromName,
      replyTargetEmail: trustedWhatsAppRelay ? sourceFromEmail : (trustedRelay ? externalReplyToEmail : (externalReplyToEmail || fromEmail)),
      messageSource: trustedWhatsAppRelay ? 'whatsapp_relay' : (trustedSupportRelay ? 'support_chat_offer_relay' : (trustedFormRelay ? 'customer_form_relay' : 'external_email')),
      trustedSupportRelay,
      trustedFormRelay,
      trustedWhatsAppRelay,
      customerPhone: trustedWhatsAppRelay ? whatsappPhone : '',
      whatsappTrackingId: trustedWhatsAppRelay ? String(whatsappTrackingMatch?.[1] || '') : '',
      receivedAt,
      triggerBodyPreview: bodyText.slice(0, 1000),
      latestMessageText,
      knowledgeQuery,
      quoteToken,
      offerUrl,
      quoteNumber,
      offerLookupQuery,
      offerOrFilter: '(' + offerFilters.join(',') + ')',
      orderOrFilter: '(' + orderFilters.join(',') + ')',
      emailDomain,
      organizationLookupEnabled,
      organizationSearchTerm,
      organizationSearchKql,
      contextSince,
      contextSinceKql,
      contextWindowReason,
      explicitHistoricalRequest,
      idempotencyKey: 'ai-email-v2:' + (internetMessageId || messageId),
      _startTime: now,
    },
  });
}

return output;

const normalized = $('Normalize Email').first().json;
const currentPayload = $('Fetch Current Message').first().json.body ?? $('Fetch Current Message').first().json;
const currentRows = Array.isArray(currentPayload.value) ? currentPayload.value : [];
let sourceMessage = currentRows.find((m) => String(m.id || '') === String(normalized.messageId || ''))
  || currentRows.find((m) => String(m.internetMessageId || '').toLowerCase() === String(normalized.internetMessageId || '').toLowerCase())
  || currentRows[0]
  || {};
if (normalized.messageSource === 'whatsapp_relay' && !sourceMessage.hasAttachments) {
  const orgPayload = $('Fetch Organization Messages').first().json.body ?? $('Fetch Organization Messages').first().json;
  const orgRows = Array.isArray(orgPayload.value) ? orgPayload.value : [];
  const digits = String(normalized.customerPhone || '').replace(/\D/g, '').slice(-10);
  const receivedMs = Date.parse(normalized.receivedAt || 0);
  const candidates = orgRows
    .filter((m) => Boolean(m.hasAttachments) && (!digits || JSON.stringify([m.subject, m.bodyPreview, m.body?.content]).replace(/\D/g, '').includes(digits)))
    .sort((a, b) => Math.abs(Date.parse(a.receivedDateTime || 0) - receivedMs) - Math.abs(Date.parse(b.receivedDateTime || 0) - receivedMs));
  if (candidates[0]) sourceMessage = candidates[0];
}
const sourceMessageId = String(sourceMessage.id || normalized.messageId || '');
const response = $('Fetch Attachment Metadata').first().json;
const payload = response.body ?? response;
const attachments = Array.isArray(payload?.value) ? payload.value : [];
const allowed = new Set(['application/pdf', 'image/jpeg', 'image/png', 'image/webp', 'image/gif']);
const maxEach = 5 * 1024 * 1024;
const maxTotal = 12 * 1024 * 1024;
const maxCount = 5;
let total = 0;
const selected = [];
const manifest = [];

for (const attachment of attachments) {
  const entry = {
    id: String(attachment.id || ''),
    name: String(attachment.name || 'Anhang').slice(0, 240),
    contentType: String(attachment.contentType || 'application/octet-stream').toLowerCase(),
    size: Number(attachment.size || 0),
    isInline: Boolean(attachment.isInline),
    status: 'skipped',
    reason: '',
  };

  if (!entry.id) entry.reason = 'missing_id';
  else if (entry.isInline) entry.reason = 'inline_asset';
  else if (!allowed.has(entry.contentType)) entry.reason = 'unsupported_type';
  else if (entry.size <= 0 || entry.size > maxEach) entry.reason = 'size_limit';
  else if (selected.length >= maxCount || total + entry.size > maxTotal) entry.reason = 'batch_limit';
  else {
    entry.status = 'selected';
    entry.reason = '';
    total += entry.size;
    selected.push(entry);
  }
  manifest.push(entry);
}

if (selected.length === 0) {
  return [{ json: { hasReadableAttachment: false, sourceMessageId, manifest, selectedCount: 0, selectedBytes: 0 } }];
}

return selected.map((entry, index) => ({
  json: {
    hasReadableAttachment: true,
    sourceMessageId,
    attachmentId: entry.id,
    attachmentName: entry.name,
    attachmentContentType: entry.contentType,
    attachmentSize: entry.size,
    attachmentIndex: index,
    manifest,
    selectedCount: selected.length,
    selectedBytes: total,
  },
}));

const items = $input.all();
const requestItems = $('Prepare Attachment Requests').all();
const manifest = requestItems[0]?.json?.manifest || [];
const binary = {};
const downloaded = [];
const warnings = [];

for (let index = 0; index < items.length; index++) {
  const response = items[index].json || {};
  const body = response.body ?? response;
  const contentBytes = String(body.contentBytes || '');
  const name = String(body.name || requestItems[index]?.json?.attachmentName || ('Anhang ' + (index + 1))).slice(0, 240);
  const contentType = String(body.contentType || requestItems[index]?.json?.attachmentContentType || 'application/octet-stream').toLowerCase();
  const declaredSize = Number(body.size || requestItems[index]?.json?.attachmentSize || 0);
  if (!contentBytes) {
    warnings.push(name + ': content_missing');
    continue;
  }
  const propertyName = 'attachment_' + index;
  binary[propertyName] = { data: contentBytes, mimeType: contentType, fileName: name };
  downloaded.push({ name, contentType, size: declaredSize, binaryProperty: propertyName });
}

if (downloaded.length === 0) throw new Error('Attachment download returned no readable content');

return [{
  json: {
    manifest,
    downloaded,
    warnings,
    attachmentBinaryNames: downloaded.map((item) => item.binaryProperty),
    attachmentManifestText: JSON.stringify({ manifest, downloaded, warnings }).slice(0, 8000),
  },
  binary,
}];

function extractText(value) {
  if (!value || typeof value !== 'object') return String(value || '');
  if (typeof value.text === 'string') return value.text;
  if (typeof value.response === 'string') return value.response;
  if (typeof value.mergedResponse === 'string') return value.mergedResponse;
  if (Array.isArray(value.content)) return value.content.map((part) => part?.text || '').join('\n');
  if (Array.isArray(value.output)) return value.output.flatMap((item) => item?.content || []).map((part) => part?.text || '').join('\n');
  return '';
}

const source = $('Aggregate Downloaded Attachments').first().json;
const rawText = extractText($input.first().json).trim();
let parsed;
try {
  parsed = JSON.parse(rawText.replace(/^\x60{3}(?:json)?\s*/i, '').replace(/\s*\x60{3}$/, ''));
} catch (error) {
  parsed = {
    files: [],
    warnings: ['attachment_analysis_invalid_json'],
    possible_prompt_injection: false,
    analysis_failed: true,
  };
}

const files = Array.isArray(parsed.files) ? parsed.files.slice(0, 5).map((file) => ({
  name: String(file?.name || '').slice(0, 240),
  document_type: ['order_confirmation', 'delivery_note', 'invoice', 'artwork', 'other'].includes(String(file?.document_type || ''))
    ? String(file.document_type)
    : 'other',
  summary: String(file?.summary || '').slice(0, 1800),
  detected_numbers: Array.isArray(file?.detected_numbers) ? file.detected_numbers.slice(0, 20).map((v) => String(v).slice(0, 120)) : [],
