  }
}

function recipientAddresses(message) {
  return [
    message?.from?.emailAddress?.address,
    ...(Array.isArray(message?.toRecipients) ? message.toRecipients.map((entry) => entry?.emailAddress?.address) : []),
    ...(Array.isArray(message?.ccRecipients) ? message.ccRecipients.map((entry) => entry?.emailAddress?.address) : []),
    ...(Array.isArray(message?.bccRecipients) ? message.bccRecipients.map((entry) => entry?.emailAddress?.address) : []),
  ].map((value) => String(value || '').trim().toLowerCase()).filter(Boolean);
}

function customerSafeOfferStatus(value) {
