function claimsAttachment(text, definition) {
  const cue = /\b(anbei|im anhang|beigefügt|angehängt|hochgeladen|beiliegend|attached|attachment|enclosed)\b/i;
  const value = String(text || '');
  const cueMatches = [...value.matchAll(new RegExp(cue.source, 'gi'))];
  const typeMatches = [...value.matchAll(new RegExp(definition.claimPattern.source, 'gi'))];
  return cueMatches.some((cueMatch) => typeMatches.some((typeMatch) => Math.abs(cueMatch.index - typeMatch.index) <= 140));
}

function inferAttachmentType(name) {
