      ? /\b(lieferschein|delivery note)\b/i
      : request.type === 'invoice'
        ? /\b(rechnung|invoice)\b/i
        : /\b(druckdatei|grafikdatei|druckdaten|logo(?:datei)?|artwork|print file)\b/i;
  if (!labelPattern.test(draftPlain) || !requestVerbPattern.test(draftPlain)) validationReasons.push('missing_attachment_not_requested:' + request.type);
}

const verified = String(meta.verifiedFactsText || '').toLowerCase();
const amountTokens = draftPlain.match(/\b\d{1,6}(?:[.,]\d{2})?\s*(?:€|eur)/gi) || [];
const allowedFinancialCents = new Set(
  (Array.isArray(meta.factsPackage?.facts) ? meta.factsPackage.facts : [])
    .filter((fact) => fact?.customer_safe === true && fact?.kind === 'money_cents' && Number.isFinite(Number(fact?.value)))
    .map((fact) => Math.round(Number(fact.value)))
);
for (const token of amountTokens) {
  const compact = token.toLowerCase().replace(/\s+/g, '');
  const numeric = Number((compact.match(/\d{1,6}(?:[.,]\d{2})?/)?.[0] || '').replace(',', '.'));
  const tokenCents = Number.isFinite(numeric) ? Math.round(numeric * 100) : null;
  if (tokenCents === null || !allowedFinancialCents.has(tokenCents)) {
    validationReasons.push('unverified_amount');
    break;
  }
}
const normalizedVerified = verified.replace(/\s+/g, '').toLowerCase();
const definitiveReferences = [
  ...(draftPlain.match(/#?NEONT\d{3,}/gi) || []),
  ...(draftPlain.match(/\bA\/N\s*\d{3,}\b/gi) || []),
  ...(draftPlain.match(/https?:\/\/[^\s<]+/gi) || []),
  ...(draftPlain.match(/\b\d{1,2}\.\d{1,2}\.20\d{2}\b/g) || []),
];
for (const reference of definitiveReferences) {
  if (!normalizedVerified.includes(String(reference).replace(/\s+/g, '').toLowerCase())) {
    validationReasons.push('unverified_reference');
    break;
  }
}
if ((amountTokens.length > 0 || definitiveReferences.length > 0) && factUseIds.length === 0) validationReasons.push('missing_fact_references');

const financialVerified = meta.financialReconciliation?.status === 'balanced'
  && meta.financialReconciliation?.equation_verified === true
  && meta.financialReconciliation?.requires_human_approval === true;
const nonFinancialHighRisk = /\b(anwalt|rechtsanwalt|klage|mahnung|widerruf|stornier|kündig|schaden|haftung|frist|datenschutz|dsgvo|chargeback|paypal konflikt)\b/i.test(String(meta.currentText || ''));
const deterministicFinancialRender = financialVerified
  && expectedLanguage === 'de'
  && !nonFinancialHighRisk
  && !meta.possiblePromptInjection;
if (deterministicFinancialRender) {
  validationReasons.length = 0;
  if (!greeting || greeting.length > 180) greeting = meta.fromName ? 'Guten Tag ' + meta.fromName + ',' : 'Guten Tag,';
  const eur = (cents) => (Number(cents || 0) / 100).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
  const reconciliation = meta.financialReconciliation;
  paragraphs = [
    'ich habe das unterschriebene Angebot, die Shopify-Bestellung und die Preisangaben im bisherigen Verlauf noch einmal miteinander abgeglichen.',
    'Im unterschriebenen Angebot wurden ursprünglich ' + eur(reconciliation.signed_gross_cents) + ' brutto berechnet. Der korrigierte Nettopreis des Schildes beträgt ' + eur(reconciliation.corrected_main_net_cents) + '. Zusammen mit den im Angebot ausgewählten Zusatzoptionen ergibt sich ein korrigierter Gesamtbetrag von ' + eur(reconciliation.corrected_gross_cents) + ' brutto.',
    'Die bereits gezahlten ' + eur(reconciliation.paid_cents) + ' werden dabei angerechnet. Die neue Rechnung über ' + eur(reconciliation.difference_cents) + ' ist genau die Differenz: ' + eur(reconciliation.paid_cents) + ' + ' + eur(reconciliation.difference_cents) + ' = ' + eur(reconciliation.corrected_gross_cents) + '. Sie zahlen den bereits geleisteten Betrag also nicht noch einmal.',
  ];
  closing = 'Viele Grüße';
}
const highRiskBlocksDraft = (meta.deterministicRiskLevel === 'high' || riskLevel === 'high')
  && !(financialVerified && !nonFinancialHighRisk);
const forceFallback = validationReasons.length > 0 || highRiskBlocksDraft || meta.possiblePromptInjection;
if (forceFallback) {
  if (missingAttachmentRequests.length > 0 && expectedLanguage === 'de') {
    const informal = /\b(du|dein(?:e|en|er|es)?|dir|dich)\b/i.test(String(meta.currentText || ''));
    const missingLabels = missingAttachmentRequests.map((entry) => entry.label);
    const missingLabelText = missingLabels.length === 1 ? missingLabels[0] : missingLabels.join(', ');
    const receivedLabels = [...new Set((meta.actualCustomerAttachments || []).map((entry) => {
      if (entry.document_type === 'delivery_note') return 'Lieferschein';
      if (entry.document_type === 'invoice') return 'Rechnung';
      if (entry.document_type === 'order_confirmation') return 'Bestellbestätigung';
      return '';
    }).filter(Boolean))];
    greeting = meta.fromName ? (informal ? 'Hallo ' : 'Guten Tag ') + meta.fromName + ',' : (informal ? 'Hallo,' : 'Guten Tag,');
    paragraphs = [
      receivedLabels.length > 0
        ? 'vielen Dank für ' + (informal ? 'deine' : 'Ihre') + ' Nachricht. Im Anhang ' + (receivedLabels.length === 1 ? 'ist derzeit ' : 'sind derzeit ') + receivedLabels.join(', ') + ' vorhanden.'
        : 'vielen Dank für ' + (informal ? 'deine' : 'Ihre') + ' Nachricht.',
      informal
        ? 'Du schreibst, dass auch die ' + missingLabelText + ' beigefügt ist. Diese Datei ist im Anhang aktuell nicht enthalten. Bitte schicke sie uns noch einmal, ' + missingAttachmentRequests[0].reason + '.'
        : 'Sie schreiben, dass auch die ' + missingLabelText + ' beigefügt ist. Diese Datei ist im Anhang aktuell nicht enthalten. Bitte senden Sie sie uns noch einmal, ' + missingAttachmentRequests[0].reason + '.',
    ];
    closing = 'Viele Grüße';
  } else if (missingAttachmentRequests.length > 0 && expectedLanguage === 'en') {
    greeting = meta.fromName ? 'Hello ' + meta.fromName + ',' : 'Hello,';
    paragraphs = [
      'Thank you for your message. We checked the files that are actually attached.',
      'The document you referred to is not included in the attachment. Please send it again so we can verify the required details.',
    ];
    closing = 'Best regards';
  } else if (expectedLanguage === 'en' && replyLengthClass === 'ack_only') {
    greeting = meta.fromName ? 'Hello ' + meta.fromName + ',' : 'Hello,';
    paragraphs = ['Thank you for the clarification. We have noted it.'];
    closing = 'Best regards';
  } else if (expectedLanguage === 'en') {
    greeting = meta.fromName ? 'Hello ' + meta.fromName + ',' : 'Hello,';
    paragraphs = [
      'Thank you for your message. We have received your request and the available documents.',
      'To provide a reliable answer, we will review the details internally and get back to you afterwards.',
    ];
    closing = 'Best regards';
  } else if (replyLengthClass === 'ack_only') {
    const informal = /\b(du|dein(?:e|en|er|es)?|dir|dich)\b/i.test(String(meta.currentText || ''));
    greeting = meta.fromName ? (informal ? 'Hallo ' : 'Guten Tag ') + meta.fromName + ',' : (informal ? 'Hallo,' : 'Guten Tag,');
    paragraphs = [informal ? 'danke für die Klarstellung. Wir haben sie so aufgenommen.' : 'vielen Dank für die Klarstellung. Wir haben sie so aufgenommen.'];
    closing = 'Viele Grüße';
  } else {
    greeting = meta.fromName ? 'Guten Tag ' + meta.fromName + ',' : 'Guten Tag,';
    paragraphs = [
      'vielen Dank für Ihre Nachricht. Wir haben Ihr Anliegen und die vorliegenden Unterlagen erhalten.',
      'Damit wir Ihnen hierzu eine verlässliche Auskunft geben können, prüfen wir die Angaben noch einmal intern und melden uns anschließend bei Ihnen.',
    ];
    closing = 'Viele Grüße';
