parameters.jsCode:
const normalized = $('Normalize Email').first().json;
const incoming = $input.first().json || {};
let message = String(incoming.error?.message || incoming.message || incoming.description || 'Unknown workflow error');
message = message.replace(/[\u0000-\u001F]+/g, ' ').slice(0, 1500);
let rendered = null;
let draftResponse = null;
try { rendered = $('Validate and Render').first().json; } catch (error) {}
try { draftResponse = $('Create Reply Draft').first().json; } catch (error) {}
const draftBody = draftResponse?.body ?? draftResponse;
const draftCreated = Boolean(draftBody?.id);
const statusCode = Number(incoming.error?.httpCode || incoming.error?.statusCode || incoming.statusCode || 0);
const retryable = statusCode === 0
  || statusCode === 404
  || statusCode === 408
  || statusCode === 409
  || statusCode === 425
  || statusCode === 429
  || statusCode >= 500
  || /timeout|temporar|rate limit|resource .* not be found|socket|connection|econn/i.test(message);

return [{ json: {
  request_id: normalized.idempotencyKey,
  message_id: rendered?.messageId || normalized.messageId,
  internet_message_id: normalized.internetMessageId || '',
  conversation_id: normalized.conversationId,
  from_email: normalized.fromEmail,
  from_name: normalized.fromName,
  subject: normalized.subject,
  message_source: normalized.messageSource,
  body_preview: String(rendered?.currentText || normalized.triggerBodyPreview || '').slice(0, 500),
  category: rendered?.category || 'general',
  confidence: rendered?.confidence || 0,
  order_found: Boolean(rendered?.orderCount > 0),
  order_count: Number(rendered?.orderCount || 0),
  knowledge_version_ids: Array.isArray(rendered?.knowledgeVersionIds) ? rendered.knowledgeVersionIds.slice(0, 8) : [],
  knowledge_match_count: Number(rendered?.knowledgeMatchCount || 0),
  draft_created: draftCreated,
  draft_id: draftBody?.id || '',
  draft_body_preview: String(rendered?.draftReplyText || '').slice(0, 500),
  error_message: message,
  latest_message_fingerprint: rendered?.latestMessageFingerprint || '',
  reply_length_class: rendered?.replyLengthClass || null,
  risk_level: rendered?.riskLevel || rendered?.deterministicRiskLevel || null,
  context_snapshot: rendered ? {
    customer_context: rendered.customerContext || {},
    attachment_claims: rendered.claimedAttachmentTypes || [],
    missing_attachments: rendered.missingClaimedAttachmentRequests || [],
    channel: rendered.messageSource || normalized.messageSource,
    evidence_resolver_version: rendered.evidenceResolverVersion || '',
    financial_reconciliation: rendered.financialReconciliation || null,
  } : {},
  retryable,
  processing_time_ms: Math.max(0, Date.now() - Number(normalized._startTime || Date.now())),
} }];

let record = {};
try { record = $('Build Failure Record').first().json; } catch (error) {}
const incoming = $input.first().json || {};
throw new Error('AI Email Agent v2 failed: ' + String(record.error_message || incoming.error?.message || incoming.message || 'unknown error'));
return [];

function bodyOf(name) {
  const response = $(name).first().json || {};
  return response.body ?? response;
}
function stripHtml(value) {
  return String(value || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/\s+/g, ' ')
    .trim();
}
const normalized = $('Normalize Email').first().json;
const currentResponse = bodyOf('Fetch Current Message');
const organizationResponse = bodyOf('Fetch Organization Messages');
const customerContext = bodyOf('Resolve Customer Context');
const placeholderOrganization = String(customerContext?.organization_id || '') === 'a0000000-0000-0000-0000-000000000001';
const relatedEmails = !placeholderOrganization && Array.isArray(customerContext?.related_emails)
  ? [...new Set(customerContext.related_emails.map((value) => String(value || '').trim().toLowerCase()).filter(Boolean))].slice(0, 16)
  : [normalized.fromEmail].filter(Boolean);
const currentMessages = Array.isArray(currentResponse?.value) ? currentResponse.value : [];
const organizationMessages = Array.isArray(organizationResponse?.value) ? organizationResponse.value : [];
const current = currentMessages.find((m) => String(m.id || '') === String(normalized.messageId || ''))
  || currentMessages.find((m) => String(m.internetMessageId || '').toLowerCase() === String(normalized.internetMessageId || '').toLowerCase())
  || currentMessages[0]
  || {};
const currentText = normalized.messageSource === 'whatsapp_relay'
  ? String(normalized.latestMessageText || normalized.triggerBodyPreview || '').slice(0, 12000)
  : stripHtml(current.body?.content || current.bodyPreview || normalized.latestMessageText || '').slice(0, 12000);
const seen = new Set();
const threadMessages = [...currentMessages, ...organizationMessages]
  .filter((message) => {
    const key = String(message.id || message.internetMessageId || '');
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  })
  .sort((a, b) => Date.parse(a.receivedDateTime || a.sentDateTime || 0) - Date.parse(b.receivedDateTime || b.sentDateTime || 0))
  .slice(-50)
  .map((message) => ({
    id: message.id,
    internetMessageId: message.internetMessageId,
    from: message.from,
    toRecipients: message.toRecipients,
    ccRecipients: message.ccRecipients,
    receivedDateTime: message.receivedDateTime,
    sentDateTime: message.sentDateTime,
    subject: String(message.subject || '').slice(0, 500),
    body: { contentType: message.body?.contentType || 'text', content: String(message.body?.content || '').slice(0, 18000) },
    bodyPreview: String(message.bodyPreview || '').slice(0, 1200),
  }));
return [{ json: {
  fromEmail: normalized.fromEmail,
  customerEmail: normalized.fromEmail,
  fromName: normalized.fromName,
  customerPhone: normalized.customerPhone || '',
  messageSource: normalized.messageSource,
  relatedEmails,
  organizationDomain: normalized.organizationLookupEnabled ? normalized.emailDomain : '',
  organizationLookupEnabled: Boolean(normalized.organizationLookupEnabled && !placeholderOrganization),
  organizationId: placeholderOrganization ? null : (customerContext?.organization_id || null),
  subject: normalized.subject,
  currentText,
  contextSince: normalized.contextSince,
  threadMessages,
} }];

const base = $("Build Draft Prompt").first().json;
const response = $input.first().json || {};
const rawProfile = response.body ?? response;
const structurallySafe = rawProfile
  && rawProfile.version === "email-style-profile-v1"
  && rawProfile.facts_or_customer_content_included === false
  && rawProfile.automatic_prompt_rewrite_allowed === false;
const approvedCount = structurallySafe ? Math.max(0, Number(rawProfile.approved_sample_count || 0)) : 0;
const recommendedWords = structurallySafe ? Number(rawProfile.recommended_max_words || 0) : 0;
const eligible = structurallySafe
  && rawProfile.eligible === true
  && approvedCount >= 3
  && Number.isFinite(recommendedWords)
  && recommendedWords > 0;
const approvedStyleProfile = {
  version: "email-style-profile-v1",
  eligible,
  approved_sample_count: approvedCount,
  window_days: structurallySafe ? Number(rawProfile.window_days || 90) : 90,
  recommended_max_words: eligible ? Math.round(recommendedWords) : null,
  prefer_shorter: eligible && rawProfile.prefer_shorter === true,
  facts_or_customer_content_included: false,
  automatic_prompt_rewrite_allowed: false,
};
if (!eligible) {
  return [{ json: { ...base, approvedStyleProfile } }];
}

const currentLimits = base.replyLengthLimits && typeof base.replyLengthLimits === "object"
  ? base.replyLengthLimits
  : { max_paragraphs: 3, max_characters: 1400 };
const className = base.replyLengthClass || "simple";
const minimumCharacters = className === "ack_only" ? 250 : (className === "complex" ? 900 : 500);
const learnedCharacterLimit = Math.max(minimumCharacters, Math.round(recommendedWords * 9));
const learnedParagraphLimit = approvedStyleProfile.prefer_shorter
  ? (className === "ack_only" ? 2 : (className === "complex" ? 4 : 2))
  : Number(currentLimits.max_paragraphs || 3);
const replyLengthLimits = {
  max_paragraphs: Math.max(1, Math.min(Number(currentLimits.max_paragraphs || 3), learnedParagraphLimit)),
  max_characters: Math.max(minimumCharacters, Math.min(Number(currentLimits.max_characters || 1400), learnedCharacterLimit)),
};
const styleInstruction = [
  "",
  "HUMAN-APPROVED STYLE PROFILE:",
  "At least " + approvedCount + " human-reviewed replies support a target of at most " + Math.round(recommendedWords) + " words for this channel and reply class.",
  approvedStyleProfile.prefer_shorter ? "Prefer the shortest complete answer that resolves the customer's request." : "Keep the answer concise without omitting necessary questions or verified facts.",
  "This profile controls length and style only. Never copy names, facts, amounts, dates, attachments, promises, or customer-specific wording from prior replies.",
].join("\n");
const styleContext = [
  "",
  "<HUMAN_APPROVED_STYLE_PROFILE>",
  JSON.stringify(approvedStyleProfile),
  "</HUMAN_APPROVED_STYLE_PROFILE>",
].join("\n");

return [{ json: {
  ...base,
  approvedStyleProfile,
  replyLengthLimits,
  systemPrompt: String(base.systemPrompt || "") + styleInstruction,
  userContext: String(base.userContext || "") + styleContext,
} }];
